461					plainBytes = localData
462				} else if envelopeData, ok := blobsToUpload[entry.BlobHash]; ok {
463					var err error
464					plainBytes, err = vault.DecryptPayload(envelopeData, e.VaultKey)
465					if err != nil {
466						return nil, fmt.Errorf("sync: failed to decrypt local blob for %s: %w", path, err)
467					}
468				} else {
469					blobBytes, err := e.Client.GetBlob(ctx, e.VaultID, entry.BlobHash)
470					if err != nil {
471						return nil, fmt.Errorf("sync: failed to fetch blob %s for %s: %w", entry.BlobHash, path, err)
472					}
473					plainBytes, err = vault.DecryptPayload(blobBytes, e.VaultKey)
474					if err != nil {
475						return nil, fmt.Errorf("sync: failed to decrypt %s: %w", path, err)
476					}
477				}
478	
479				fullPath := writeTargets[path]
480				_ = os.MkdirAll(filepath.Dir(fullPath), 0o755)
481				_ = os.WriteFile(fullPath, plainBytes, 0o644)
482			}
483	
484			for _, path := range diff.Deleted {
485				_ = os.Remove(deleteTargets[path])
486			}
487	
488			// Upload new blobs
489			if len(candidateHashes) > 0 {
490				missing, err := e.Client.CheckMissingBlobs(ctx, e.VaultID, candidateHashes)
491				if err == nil {
492					for _, h := range missing {
493						if d, ok := blobsToUpload[h]; ok {
494							_ = e.Client.PutBlob(ctx, e.VaultID, h, d)
495						}
496					}
497				}
498			}
499	
500			// Upload merged tree
501			mergedTreeBytes, _ := reconcileRes.MergedTree.Serialize()
502			mergedTreeEnv, _ := vault.EncryptPayload(mergedTreeBytes, e.VaultKey)
503			mergedTreeHash := vault.HashBlob(mergedTreeEnv)
504			_ = e.Client.PutBlob(ctx, e.VaultID, mergedTreeHash, mergedTreeEnv)
505	
506			// Create merge commit pointing to remoteHead
507			mergeCommit := vault.NewCommit(&remoteHead, mergedTreeHash, author, "Reconcile merge: "+message)
508			mergeCommitBytes, _ := mergeCommit.Serialize()
509			mergeCommitEnv, _ := vault.EncryptPayload(mergeCommitBytes, e.VaultKey)
510			mergeCommitHash := vault.HashBlob(mergeCommitEnv)
511			_ = e.Client.PutBlob(ctx, e.VaultID, mergeCommitHash, mergeCommitEnv)
512	
513			resp, err := e.Client.Commit(ctx, e.VaultID, mergeCommitHash, &remoteHead)
514			if err != nil {
515				var raceErr *HeadConflictError
516				if errors.As(err, &raceErr) {
517					// Server head advanced during reconciliation, retry with new head
518					remoteHead = raceErr.CurrentHead
519					e.cachedTree = remoteTree
520					continue
521				}
522				return nil, fmt.Errorf("sync: failed to commit merged head: %w", err)
523			}
524	
525			e.cachedHead = resp.Head
526			e.cachedTree = reconcileRes.MergedTree
527	
528			if err := e.saveState(); err != nil {
529				return nil, fmt.Errorf("sync: merged commit %s was accepted by the hub, but persisting the sync state failed: %w", resp.Head, err)
530			}
531	
532			return &SyncResult{
533				CommitHash: resp.Head,
534				Conflicts:  reconcileRes.Conflicts,
535			}, nil
536		}
537	
538		return nil, fmt.Errorf("sync: exceeded maximum reconciliation retries (%d)", DefaultMaxSyncRetries)
539	}
