541	// fetchPlaintext downloads and decrypts a blob from the hub.
542	func (e *Engine) fetchPlaintext(ctx context.Context, blobHash string) ([]byte, error) {
543		envelope, err := e.Client.GetBlob(ctx, e.VaultID, blobHash)
544		if err != nil {
545			return nil, err
546		}
547		return vault.DecryptPayload(envelope, e.VaultKey)
548	}
